from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with shared memory and loop unrolling
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile of A into shared memory
        int loadRow = row;
        int loadCol = tile * TILE_SIZE + threadIdx.x;
        if (loadRow < N && loadCol < N) {
            sA[threadIdx.y][threadIdx.x] = A[loadRow * N + loadCol];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        loadRow = tile * TILE_SIZE + threadIdx.y;
        loadCol = col;
        if (loadRow < N && loadCol < N) {
            sB[threadIdx.y][threadIdx.x] = B[loadRow * N + loadCol];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial product with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            sum += sA[threadIdx.y][k] * sB[k][threadIdx.x];
            sum += sA[threadIdx.y][k+1] * sB[k+1][threadIdx.x];
            sum += sA[threadIdx.y][k+2] * sB[k+2][threadIdx.x];
            sum += sA[threadIdx.y][k+3] * sB[k+3][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threads(TILE_SIZE, TILE_SIZE);
    dim3 blocks((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

